cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && for b in rachel monica phoebe joey chandler ross; do git fetch origin friend/$b; done && python3 - <<'EOF'
import subprocess,re
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    out=subprocess.check_output(['git','log','--format=%H%x09%B%x00', f'origin/friend/{b}'], text=True)
    for entry in out.split('\x00'):
        if 'Friend-Message: 1' in entry:
            m=re.search(r'Episode:\s*(\S+)', entry)
            ep=m.group(1) if m else '?'
            if ep=='S06/E03':
                sha=entry.split('\t',1)[0].strip()
                print(b, sha[:12])
EOF
